   102	    pub fn create(source: &'a [u8], tokens: &'a [XmlToken]) -> Result<Self, CssError> {
   103	        let mut sheet = Self { source, tokens, rules: Vec::new(), declaration_count: 0, css_bytes: 0,
   104	            match_tests: 0, selector_visits: 0, hit_limit: false };
   105	        for (index, token) in tokens.iter().enumerate() {
   106	            if token.kind != TokenKind::StartElement || !is_style_element(source, token) { continue; }
   107	            let mut cursor = index + 1;
   108	            while cursor < tokens.len() && tokens[cursor].kind != TokenKind::EndElement {
   109	                let child = &tokens[cursor];
   110	                if matches!(child.kind, TokenKind::Text | TokenKind::Cdata) {
   111	                    let bytes = checked_slice(source, child.value)?;
   112	                    sheet.css_bytes = sheet.css_bytes.checked_add(bytes.len()).ok_or(CssError::Limit)?;
   113	                    if sheet.css_bytes > MAX_BYTES { return Err(CssError::Limit); }
   114	                    sheet.parse_stylesheet(child.value.offset, child.value.offset + child.value.length)?;
   115	                }
   116	                cursor += 1;
   117	            }
   118	        }
   119	        Ok(sheet)
   120	    }
