   131	            return Err(CssError::Limit);
   132	        }
   133	        let token = tokens.get(element).ok_or(CssError::Limit)?;
   134	        if !is_element(token) { return Err(CssError::Limit); }
   135	        let mut paint = parent.copied().unwrap_or_else(CssPaint::initial);
   136	        paint.source = Some(source);
